function identify(s){if(typeof s.runId!=='string'||s.runId.length>120)s.runId=window.crypto?.randomUUID?.()||'run-'+Date.now()+'-'+Math.random().toString(36).slice(2);return s;}
function validateState(raw){const s=identify(market.migrateLegacy(market.validate(raw)));if(s.mode==='free'&&!progression.freeUnlocked)throw Error('請先完成人生模式一輪，再讀取自由模式存檔');s.chats??=[];if(s.activeEvent&&!story.events.some(e=>e.id===s.activeEvent))throw Error('未知劇情事件');if(!s.seen.every(id=>story.events.some(e=>e.id===id)))throw Error('未知劇情紀錄');return s;}
function pack(s=state){if(s===state)syncPlaytime();market.stamp(s);return {format:'taigu-warrior-save',version:1,savedAt:new Date().toISOString(),state:s};}
function writeStorage(key,value){if(resettingRecords)return false;try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageFailed=true;document.querySelector('.local-tag').textContent='⚠ 自動存檔不可用';notify('瀏覽器目前無法儲存，請確認有可用的儲存空間。');return false;}}
function save(){if(!storageFailed)writeStorage(KEY+'.auto',pack());}
function load(){for(let i=1;i<=3;i++){try{const p=JSON.parse(localStorage.getItem(KEY+'.slot'+i)||'null');if(p?.state?.datasetEnd===data.end&&!p.state.datasetPrefix){market.validate(p.state);market.stamp(p.state);localStorage.setItem(KEY+'.slot'+i,JSON.stringify(p));}}catch{}}try{const text=localStorage.getItem(KEY+'.auto');if(text){const p=JSON.parse(text);state=validateState(p.state);}}catch(e){notify('存檔無法載入：'+e.message+'。請嘗試讀取另一個進度欄位。');try{const raw=localStorage.getItem(KEY+'.auto');if(raw)localStorage.setItem(KEY+'.recovery',raw);}catch{} }}
