function hasProgress(s=state){return !s.opening||s.day>=0||s.log.length>0;}
function rememberRun(reason){
 if(!hasProgress())return;syncPlaytime();identify(state);const r=TaiguRecords.snapshot(market,state,reason);const signature=JSON.stringify([r.id,r.date,r.status,r.reason,r.equity,r.trades,r.spent,r.playTimeMs,r.skillUses]);if(signature===recordSignature)return;
 book=TaiguRecords.upsert(book,r);communityHome.report(r);syncSkillProfile();if(writeStorage(KEY+'.records',book))recordSignature=signature;
}
function renderTitle(){
 $('skillPointCount').textContent=skillProfile.points+' 點';
 const unlockNotes=[];if(progression.marginUnlocked)unlockNotes.push('✦ 融資已解鎖');if(progression.marginDebtAchievement)unlockNotes.push('🏅 負債轉生');$('titleUnlocks').textContent=unlockNotes.join('　');
 const recent=hasProgress()?TaiguRecords.snapshot(market,state):book.runs.at(-1),best=TaiguRecords.best(book,state.mode);
 $('menuFree').disabled=!progression.freeUnlocked;$('menuFree').querySelector('span').textContent=progression.freeUnlocked?'自由模式　↗':'🔒 自由模式';$('freeLockNote').textContent=progression.freeUnlocked?'已解鎖 · 自由逐日交易':'完成人生模式才可進行';$('menuContinue').disabled=!hasProgress();$('menuContinue').innerHTML=(state.status==='playing'?'繼續'+(state.mode==='life'?'人生模式':'自由模式'):'查看上次結局')+' <span>↗</span>';
 $('lastRunValue').textContent=recent?dollars(recent.equity):'還沒有冒險紀錄';$('lastRunNote').textContent=recent?`${recent.date.replaceAll('-','.')} · 超額 ${(recent.alpha>=0?'+':'')+recent.alpha.toFixed(2)} 百分點`:'每一次決定，都會被留下。';
 $('shareBest').disabled=!best;$('bestRunValue').textContent=best?(best.alpha>=0?'+':'')+best.alpha.toFixed(2)+' 百分點':'等你寫下第一個結局';$('bestRunNote').textContent=best?`${best.status==='won'?'成功超越 0050':'已完成一輪'} · 總資產 ${dollars(best.equity)}`:'依完整一輪的超額報酬比較。';
}
function highlightsHTML(r){
 const amount=n=>'$'+n.toLocaleString('zh-TW',{minimumFractionDigits:2,maximumFractionDigits:2});
 const signed=n=>(n>=0?'+':'−')+amount(Math.abs(n));
 const ready=r.statsVersion===1&&r.statsComplete;
 const card=(trade,title,empty)=>`<article class="highlight-card"><span>${title}</span>${trade?`<strong class="${tone(trade.pnl)}">${signed(trade.pnl)}</strong><b>${esc(data.instruments[trade.id]?.name||trade.id)} <small>${esc(trade.id)}</small></b><p>${esc(trade.date)} · 賣出 ${fmt(trade.qty)} 股<br>成交 ${trade.price.toFixed(2)} 元 · 淨報酬 ${pct(trade.returnPct)}</p><small>分攤成本 ${amount(trade.costBasis)}<br>賣出實收 ${amount(trade.proceeds)}</small>`:`<strong class="highlight-empty">${ready?empty:'尚無可重建明細'}</strong><p>${ready?'完成賣出後自動記錄。':'舊版摘要未保留明細；若仍有該輪存檔，讀取後可重新計算。'}</p>`}</article>`;
 return `<section class="highlights">${marginRecords(r)}<h3>✦ 操作高光</h3><div class="highlight-counts"><div><span>交易次數</span><b>${r.trades} 筆</b></div><div><span>買進 / 賣出</span><b>${r.statsVersion===1?`${r.buyTrades} / ${r.sellTrades}`:'—'}</b></div><div><span>已實現淨損益</span><b class="${ready?tone(r.realizedPnl):''}">${ready?signed(r.realizedPnl):'—'}</b></div></div><div class="highlight-grid">${card(ready?r.maxGain:null,'最大獲利・依金額','尚無獲利賣出')}${card(ready?r.maxLoss:null,'最大虧損・依金額','尚無虧損賣出')}</div><p class="highlight-rules">以每筆賣出成交為一筆高光，成本採移動加權平均，扣除買賣手續費與賣出稅，融資另扣分攤利息；不含股利及未賣出的帳面損益。買一次、賣一次算 2 筆交易，取消與未成交不計。</p></section>`;
}
function showInventory(){
 if(busy)playback.stop();const v=TaiguRecords.inventory(market,state),signed=n=>(n>=0?'+':'−')+dollars(Math.abs(n));
 utility('股票庫存與損益',`<div class="inventory-date">估值日 ${esc(v.date)} · ${state.mode==='life'?'人生模式':'自由模式'}</div><div class="inventory-summary"><article><span>總資產</span><strong>${dollars(v.equity)}</strong></article><article><span>可用現金</span><strong>${dollars(v.cash)}</strong></article><article><span>持股市值</span><strong>${dollars(v.value)}</strong></article><article><span>未實現損益</span><strong class="${tone(v.pnl)}">${signed(v.pnl)}</strong><small>${pct(v.returnPct)}</small></article></div><p class="inventory-receivable">應收股利 ${dollars(v.receivable)} · 持股總成本 ${dollars(v.cost)}</p><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>股票</th><th>本輪買進日期</th><th>庫存股數</th><th>含費均價</th><th>現價</th><th>持股成本</th><th>持股市值</th><th>未實現損益</th><th>報酬率</th></tr></thead><tbody>${v.rows.length?v.rows.map(r=>'<tr><td><strong>'+esc(r.name)+'</strong><small>'+r.id+'</small></td><td>'+(r.firstBuy?esc(r.firstBuy):'舊紀錄未保留')+(r.lastBuy&&r.lastBuy!==r.firstBuy?'<small>最近 '+esc(r.lastBuy)+'</small>':'')+'</td><td>'+fmt(r.qty)+'</td><td>'+r.average.toFixed(2)+'</td><td>'+r.price.toFixed(2)+(r.priceDate!==v.date?'<small>沿用 '+esc(r.priceDate)+'</small>':'')+'</td><td>'+dollars(r.cost)+'</td><td>'+dollars(r.value)+'</td><td class="'+tone(r.pnl)+'">'+signed(r.pnl)+'</td><td class="'+tone(r.pnl)+'">'+pct(r.returnPct)+'</td></tr>').join(''):'<tr><td colspan="9" class="board-empty">目前沒有股票庫存。成交後會在這裡列出。</td></tr>'}</tbody></table></div><p class="muted-note">買進日期為本輪持倉的首次與最近買進日；部分賣出不重設首次日期。成本含買入手續費，損益未扣未來賣出費稅、不含股利。分割換發自動調整股數與均價。</p>${v.rows.map(r=>'<details class="inventory-trades"><summary>'+esc(r.name)+' '+r.id+' · 查看買賣成交紀錄</summary><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>交易日</th><th>方向</th><th>股數</th><th>成交價</th><th>成交金額</th><th>手續費</th><th>交易稅</th></tr></thead><tbody>'+r.trades.slice().reverse().map(t=>'<tr><td>'+esc(t.date)+'</td><td>'+ (t.side==='buy'?'買進':'賣出')+'</td><td>'+fmt(t.qty)+'</td><td>'+t.price.toFixed(2)+'</td><td>'+dollars(t.value)+'</td><td>'+dollars(t.fee)+'</td><td>'+dollars(t.tax)+'</td></tr>').join('')+'</tbody></table></div></details>').join('')}`);
}
function creditAffordable(cash,price){return creditMode==='margin'?market.marginAffordable(cash,price):market.affordable(cash,price);}
function creditAvailable(id=selected){return market.available(state,id,creditMode);}
function marginRecords(r){const raw=r.margin||{},m=raw.totalBorrowedCents!==undefined?{totalBorrowed:raw.totalBorrowedCents/100,totalInterest:raw.totalInterestCents/100,totalTopups:raw.totalTopupsCents/100,liquidations:raw.liquidations}:raw;return '<div class="margin-records"><span>累計融資動用<b>'+dollars(m.totalBorrowed||0)+'</b></span><span>累計融資利息<b>'+dollars(m.totalInterest||0)+'</b></span><span>補繳保證金<b>'+dollars(m.totalTopups||0)+'</b></span><span>斷頭次數<b>'+(m.liquidations||0)+' 次</b></span></div>';}
function renderCredit(){
 const m=market.marginInfo(state),enabled=!!state.margin?.enabled;if(!enabled)creditMode='cash';
   $('marginToggle').checked=creditMode==='margin';$('marginToggle').disabled=!enabled||busy||tutorialLocked();$('marginLabel').textContent=enabled?'融資':'🔒 融資';$('marginToggle').title=enabled?'勾選使用融資；取消勾選使用現股':'完成人生模式一輪後解鎖';
  $('marginStatus').hidden=!enabled||(!m.principal&&!m.call);$('marginStatus').dataset.call=!!m.call;$('marginStatus').innerHTML='<span>'+(m.call?'追繳第 '+Math.min(4,state.day-m.call.startedDay+1)+' 天':'融資帳戶')+'</span><b>'+(m.maintenance!==null?m.maintenance.toFixed(2)+'% ↗':'查看 ↗')+'</b>';
const notes=[];if(progression.marginUnlocked)notes.push('✦ 融資已解鎖');if(progression.marginDebtAchievement)notes.push('🏅 負債轉生');$('titleUnlocks').textContent=notes.join('　');
}
function showCreditHelp(){const el=$('marginDialog');$('marginDialogTitle').textContent='認識融資';$('marginDialogBody').innerHTML=TaiguMarginUI.help()+'<div class="margin-actions"><button id="marginHelpDone" class="primary">知道了</button></div>';$('marginHelpDone').onclick=()=>el.close();if(!el.open)el.showModal();}
function showMarginAccount(){
 playback.stop();const m=market.marginInfo(state),call=m.call,day=call?state.day-call.startedDay+1:0,el=$('marginDialog');$('marginDialogTitle').textContent=call?'融資追繳令':'融資帳戶';
 const banner=call?'<div class="margin-call-banner"><h3>追繳第 '+day+' 天'+(day<4?' · 第 4 天開盤斷頭':' · 等待可交易日處分')+'</h3><p>維持率 '+m.maintenance.toFixed(2)+'%。'+(day<4?'今天仍可補繳；補足 '+dollars(m.requiredTopup)+' 元可回到約 166.67%，解除追繳。':'停牌持股會在恢復交易時處分。')+'</p></div>':'';
 const target=Math.min(state.cash,m.requiredTopup),topup=call&&day<4?'<form id="marginTopupForm" class="margin-topup-form"><label for="marginTopupAmount">補保證金 · 可用現金 '+dollars(state.cash)+'<input id="marginTopupAmount" type="number" min="0.01" max="'+Math.max(0,state.cash)+'" step="0.01" value="'+Math.max(0,target).toFixed(2)+'" inputmode="decimal"></label><button id="marginFillTarget" type="button">填入解除所需金額</button><button class="primary" type="submit" '+(state.cash<=0?'disabled':'')+'>補繳保證金</button><p id="marginTopupError" class="margin-error" role="status"></p></form>':'';
 const positions=Object.entries(state.margin?.positions||{}).map(([id,p])=>'<p><b>'+esc(data.instruments[id].name)+' '+esc(id)+'</b> · '+fmt(p.qty)+' 股<br>借款 '+dollars(p.principal)+' · 未付利息 '+dollars(p.interest)+'</p>').join('');
 $('marginDialogBody').innerHTML=banner+'<div class="margin-summary"><article><span>整戶維持率</span><strong>'+(m.maintenance===null?'尚無部位':m.maintenance.toFixed(2)+'%')+'</strong></article><article><span>融資借款</span><strong>'+dollars(m.principal)+'</strong></article><article><span>未付利息</span><strong>'+dollars(m.interest)+'</strong></article><article><span>擔保金</span><strong>'+dollars(m.collateral)+'</strong></article><article><span>融資持股市值</span><strong>'+dollars(m.value)+'</strong></article><article><span>可用現金</span><strong>'+dollars(state.cash)+'</strong></article></div>'+topup+positions+marginRecords({margin:m})+'<details class="margin-guide"><summary>融資與追繳規則</summary>'+TaiguMarginUI.help()+'</details><div class="margin-actions"><button id="marginAccountDone" class="primary">'+(market.marginNeedsAction(state)?'暫不補繳，繼續':'回到遊戲')+'</button></div>';
 $('marginAccountDone').onclick=()=>{if(market.marginNeedsAction(state))market.acknowledgeMargin(state);save();el.close();render();};
 if($('marginFillTarget'))$('marginFillTarget').onclick=()=>{$('marginTopupAmount').value=m.requiredTopup.toFixed(2);};
 if($('marginTopupForm'))$('marginTopupForm').onsubmit=e=>{e.preventDefault();try{const result=market.topupMargin(state,Number($('marginTopupAmount').value));save();render();showMarginAccount();if(!result.call)notify('保證金補足，追繳令已解除。');}catch(err){$('marginTopupError').textContent=err.message;}};
 if(!el.open)el.showModal();
}
function showMarginPhone(){
 if(!market.marginNeedsAction(state)){showMarginAccount();return;}playback.stop();const m=market.marginInfo(state),day=state.day-m.call.startedDay+1,el=$('marginDialog');$('marginDialogTitle').textContent='營業員來電';
 $('marginDialogBody').innerHTML='<section class="margin-phone" data-stage="ringing"><div class="phone-meta">'+esc(market.date(state))+' · 追繳第 '+day+' 天</div><div class="phone-ring"><span aria-hidden="true">☎</span></div><p class="phone-incoming" role="status">手機震動了……</p><h3>營業員 小林</h3><p class="phone-subtitle">信用交易來電</p><div id="phoneConversation" aria-live="polite"></div><button id="phoneAccept" class="phone-answer">☎ 接聽電話</button></section>';
 music.sfx('phone');if(!el.open)el.showModal();$('phoneAccept').onclick=()=>{const stage=el.querySelector('.margin-phone');stage.dataset.stage='connected';stage.querySelector('.phone-incoming').textContent='通話中 · 信用交易通知';$('phoneAccept').hidden=true;
 const lines=day===1?['小韭你好，這裡是營業員小林。這通不是明牌，是追繳通知。','你的整戶融資維持率掉到 '+m.maintenance.toFixed(2)+'%，低於 130% 了。','今天是第 1 天，請在第 3 個交易日結束前解除追繳；第 4 天開盤會強制賣出。']:day===2?['小韭，我是小林，今天再提醒你一次。','追繳已經第 2 天，維持率目前 '+m.maintenance.toFixed(2)+'%。','還有今天和明天能補繳，別把營業員的電話當成鬧鐘喔。']:['小韭，這通真的要接。今天是追繳第 3 天。','目前維持率 '+m.maintenance.toFixed(2)+'%，今天是最後補繳日。','今天沒有解除追繳，下一個交易日開盤就會強制賣出融資持股。'];
 $('phoneConversation').innerHTML='<div class="phone-dialogue"><span class="phone-agent">小林</span><div class="call-words">'+lines.map(line=>'<p>'+esc(line)+'</p>').join('')+'</div></div><p class="phone-required">補繳 '+dollars(m.requiredTopup)+' 元可回到約 166.67%<br><small>可用現金 '+dollars(state.cash)+'</small></p><div class="phone-choices"><button id="phoneTopup" class="primary">我來補保證金</button><button id="phoneWait">今天先不補繳</button></div>';
 const skills=market.skillInfo(state);if(skills.vipRemaining>0){const vip=document.createElement('button');vip.textContent='林北VIP拉：我認識你們老闆！';vip.disabled=skills.vipRemaining<m.requiredTopup;vip.onclick=()=>{try{const amount=market.useVIP(state);save();el.close();render();notify('券商代墊 '+dollars(amount)+'，追繳令已解除。');}catch(err){notify(err.message);}};$('phoneConversation').querySelector('.phone-choices').append(vip);}if(skills.motherRemaining>0){const mom=document.createElement('button');mom.textContent='先跟媽媽借錢';mom.onclick=()=>{el.close();showSkills();};$('phoneConversation').querySelector('.phone-choices').append(mom);}$('phoneTopup').onclick=showMarginAccount;$('phoneWait').onclick=()=>{if(market.marginNeedsAction(state))market.acknowledgeMargin(state);save();el.close();render();};
 };
}

function maybeMarginCall(){if(screen==='game'&&!busy&&!tutorial.active&&!$('introDialog').open&&!$('unlockDialog').open&&!$('utilityDialog').open&&market.marginNeedsAction(state)&&!$('marginDialog').open)showMarginPhone();}
function showUnlockNotice(){
 const items=[];for(const [id,n]of Object.entries(skillProfile.awarded))if(!skillProfile.announced[id])items.push({key:'skill:'+id,title:'✦ 獲得 '+n+' 點技能點',text:'完成人生模式的獎勵已入帳！回到起始畫面的「技能」可升級媽媽10塊、林北VIP拉與奇門遁甲。'});if(progression.freeUnlocked&&!progression.notifiedFree)items.push({key:'notifiedFree',title:'✦ 自由模式已解鎖',text:'每天都可以下單，保留原有劇情與新聞事件。回到起始畫面即可開始。'});if(progression.marginUnlocked&&!progression.notifiedMargin)items.push({key:'notifiedMargin',title:'✦ 融資功能已解鎖',text:'人生模式完成一輪！之後的人生與自由模式，都能選擇 4 成本金、6 成借款，使用 2.5 倍槓桿；再挑戰一次，這次由你決定要不要使用槓桿。'});if(progression.marginDebtAchievement&&!progression.notifiedMarginDebt)items.push({key:'notifiedMarginDebt',title:'🏅 成就解鎖：負債轉生',text:'股價跌破了最後的防線，還款後的資產成為負數。這一輪結束，這個教訓會留下來。'});
 if(!items.length||$('unlockDialog').open)return;const el=$('unlockDialog');$('unlockDialogTitle').textContent='新的旅程，解鎖了';$('unlockDialogBody').innerHTML=items.map(i=>'<article class="unlock-feature '+(i.key==='notifiedMarginDebt'?'achievement':'')+'"><h3>'+i.title+'</h3><p>'+i.text+'</p></article>').join('')+(items.some(i=>i.key==='notifiedMargin')?'<button id="unlockLearnMargin" class="secondary">認識融資：維持率、追繳與斷頭</button><div id="unlockMarginGuide" hidden>'+TaiguMarginUI.help()+'</div>':'')+'<div class="unlock-actions"><button id="unlockDone" class="primary">知道了，繼續 →</button></div>';
 const done=()=>{for(const item of items){if(item.key.startsWith('skill:'))skillProfile.announced[item.key.slice(6)]=true;else progression[item.key]=true;}writeStorage(KEY+'.skills',skillProfile);writeStorage(KEY+'.progression',progression);el.close();renderTitle();setTimeout(tryAnnouncement,0);};$('unlockDone').onclick=done;$('unlockClose').onclick=done;el.oncancel=e=>{e.preventDefault();done();};if($('unlockLearnMargin'))$('unlockLearnMargin').onclick=()=>{$('unlockMarginGuide').hidden=!$('unlockMarginGuide').hidden;$('unlockLearnMargin').textContent=$('unlockMarginGuide').hidden?'認識融資：維持率、追繳與斷頭':'收起融資說明';};el.showModal();
}

function showCurrentHighlights(){syncPlaytime();const r=TaiguRecords.snapshot(market,state);utility('本輪操作高光',`<span class="story-badge">${esc(r.date)} · 本機紀錄</span>${playStats(r)}${highlightsHTML(r)}`);}
let boardRequest=0;
function boardControls(outcome,mode,place){return '<div class="board-location"><button data-board-place="online" class="'+(place==='online'?'selected':'')+'">線上排行榜</button><button data-board-place="local" class="'+(place==='local'?'selected':'')+'">本機紀錄</button></div><div class="board-modes" role="group" aria-label="排行榜遊戲模式"><button data-board-mode="life" class="'+(mode==='life'?'selected':'')+'" aria-pressed="'+(mode==='life')+'">人生模式</button><button data-board-mode="free" class="'+(mode==='free'?'selected':'')+'" aria-pressed="'+(mode==='free')+'">自由模式</button></div><div class="board-tabs" role="group" aria-label="排行榜結局"><button data-board="won" class="'+(outcome==='won'?'selected':'')+'" aria-pressed="'+(outcome==='won')+'">超額報酬榜</button><button data-board="lost" class="'+(outcome==='lost'?'selected':'')+'" aria-pressed="'+(outcome==='lost')+'">翻車紀錄榜</button></div>';}
function bindBoard(outcome,mode,place){document.querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>showLeaderboard(b.dataset.board,mode,place));document.querySelectorAll('[data-board-mode]').forEach(b=>b.onclick=()=>showLeaderboard(outcome,b.dataset.boardMode,place));document.querySelectorAll('[data-board-place]').forEach(b=>b.onclick=()=>showLeaderboard(outcome,mode,b.dataset.boardPlace));}
function boardScore(r,metric,online=false){const alpha=online?r.score/100:r.alpha;return (alpha>=0?'+':'')+alpha.toFixed(2)+' 百分點';}
function showLeaderboard(outcome='won',mode=state.mode,place='online'){
 const table=(rows,cloud)=>TaiguBoard.table(rows,{online:cloud,outcome,avatar:moodAvatar,rank:crownRank});
 if(place==='local'){
  ++boardRequest;const rows=TaiguRecords.leaderboard(book,outcome,{ruleset:mode==='life'?'tw-life-v1':'tw-v1',datasetEnd:data.end});utility('排行榜・本機紀錄',boardControls(outcome,mode,place)+'<p class="board-notice">這裡保留這個瀏覽器的完整輪次，與線上排行榜分開。</p>'+table(rows,false),'leaderboard');bindBoard(outcome,mode,place);return;
 }
 const request=++boardRequest;utility('線上排行榜',boardControls(outcome,mode,place)+'<p class="board-notice">前 100 名 · 每個匿名身分各榜保留最佳一筆</p><div id="onlineBoardSelf" class="online-rank-self">提交完整成績後，可在這裡查看自己的名次。</div><div id="onlineBoardBody"><p class="online-status" role="status">正在取得線上成績…</p></div><p class="online-submit-note">'+(outcome==='won'?'超額報酬榜收錄贏過大盤的成績。':'翻車紀錄榜收錄未贏大盤的成績。')+'依最後總資產排序；總資產相同時，比較單筆最大'+(outcome==='won'?'獲利':'虧損')+'金額、較少交易次數，再依先提交者排序。點暱稱可看交易高光。</p>','leaderboard');bindBoard(outcome,mode,place);
 Promise.allSettled([online.leaderboard(mode,outcome),online.rank(mode,outcome)]).then(results=>{
  if(request!==boardRequest||!$('utilityDialog').open||$('utilityDialog').dataset.view!=='leaderboard'||!$('onlineBoardBody'))return;
  if(results[0].status==='rejected'){$('onlineBoardBody').innerHTML='<p class="online-status error" role="status">'+esc(results[0].reason.message)+'</p><div class="online-retry"><button id="retryBoard" class="secondary">重新連線</button><button id="localBoard" class="secondary">查看本機紀錄</button></div>';$('retryBoard').onclick=()=>showLeaderboard(outcome,mode,'online');$('localBoard').onclick=()=>showLeaderboard(outcome,mode,'local');return;}
  const rows=results[0].value.items;$('onlineBoardBody').innerHTML=table(rows,true);
  document.querySelectorAll('[data-online-row]').forEach(b=>b.onclick=()=>showOnlineDetails(rows[Number(b.dataset.onlineRow)],outcome,mode));
  const mine=results[1].status==='fulfilled'?results[1].value.entry:null;if(mine)$('onlineBoardSelf').innerHTML='你的最佳名次 <b>第 '+mine.rank+' 名</b> · '+esc(mine.nickname)+' · 總資產 '+dollars(mine.equityCents/100);
 });
}
function showOnlineDetails(r,metric,mode,financing='cash'){const card=(t,title)=>'<article><h3>'+title+'</h3>'+(t?'<strong class="'+tone(t.pnlCents)+'">'+(t.pnlCents>=0?'+':'−')+dollars(Math.abs(t.pnlCents)/100)+'</strong><p>'+esc(data.instruments[t.symbol]?.name||t.symbol)+' · '+esc(t.symbol)+'<br>'+esc(t.date)+' · '+fmt(t.qty)+' 股<br>成交 '+(t.priceCents/100).toFixed(2)+' 元</p>':'<p>尚無這類賣出紀錄。</p>')+'</article>';utility('線上成績・'+r.nickname,'<div class="online-summary"><small>'+(r.mode==='life'?'人生模式':'自由模式')+' · '+(r.outcome==='won'?'成功超越 0050':'未能超越 0050')+'</small><strong>'+boardScore(r,'alpha',true)+'</strong><span>總資產 '+dollars(r.equityCents/100)+' · 成交 '+r.trades+' 筆</span></div>'+marginRecords(r)+'<div class="online-details">'+card(r.highlights.maxGain,'最大獲利・單筆淨收益')+card(r.highlights.maxLoss,'最大虧損・單筆淨收益')+'</div><div class="dialog-actions"><button id="backToBoard" class="secondary">返回排行榜</button></div><p class="online-submit-note">這是基本檢核成績，未進行完整交易重播。</p>');$('backToBoard').onclick=()=>showLeaderboard(metric,mode,'online',financing);}

const moodNames=['微笑','興奮','得意','認真','緊張','驚訝','哭哭','疲憊','生氣','期待'];
function moodAvatar(id=1){id=Number.isInteger(id)&&id>=1&&id<=10?id:1;return '<span class="mood-avatar" role="img" aria-label="心情 '+id+'：'+moodNames[id-1]+'" style="--mood-x:'+((id-1)%5)*25+'%;--mood-y:'+Math.floor((id-1)/5)*100+'%"></span>';}
function crownRank(rank){if(rank>3)return String(rank);return '<span class="crown-rank crown-'+rank+'"><svg viewBox="0 0 24 20" role="img" aria-label="'+['','金色','銀色','銅色'][rank]+'皇冠"><path d="M2 4 7 8 12 1 17 8 22 4 19 16H5Z" fill="currentColor" stroke="currentColor" stroke-linejoin="round"/><path d="M6 19H18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg><b>'+rank+'</b></span>';}
function moodPicker(selected=1){return '<fieldset class="mood-picker"><legend>這次上榜的心情</legend><div>'+moodNames.map((name,i)=>'<label title="'+name+'"><input type="radio" name="avatarId" value="'+(i+1)+'" '+(selected===i+1?'checked':'')+'>'+moodAvatar(i+1)+'<span>'+(i+1)+'</span><span class="sr-only">'+name+'</span></label>').join('')+'</div></fieldset>';}

function showOnlineSubmit(r=TaiguRecords.snapshot(market,state)){
 syncPlaytime();if(r.id===state.runId)r=TaiguRecords.snapshot(market,state);const eligible=online.eligibility(r),returnToResult=screen==='game'&&state.status!=='playing'&&r.id===state.runId;
 const receipt=online.receipt(r.id);utility('提交線上成績','<div class="online-summary"><small>'+(r.mode==='life'?'人生模式':'自由模式')+' · '+esc(r.date)+'</small><strong>'+pct(r.alpha).replace('%',' 百分點')+'</strong><span>總資產 '+dollars(r.equity)+'</span></div>'+(eligible.ok?'<form id="onlineSubmitForm" class="online-submit-form"><label>玩家暱稱<input id="onlineNickname" required minlength="2" maxlength="20" autocomplete="nickname" value="'+esc(online.read().nickname||'')+'"><span class="form-help">2–20 字，可使用中英文、數字、空格、_、- 或 .</span></label>'+moodPicker(online.read().avatarId||1)+'<p class="online-submit-note">只會送出暱稱與結算摘要，不會上傳完整存檔。每個匿名身分各榜保留最佳成績。</p><p id="onlineSubmitStatus" class="online-status" role="status"></p><button class="primary" type="submit">提交這輪成績</button></form>':'<p class="online-status">'+esc(eligible.reason)+(receipt?.rank?' 目前最佳名次：第 '+receipt.rank.rank+' 名。':'')+'</p>')+'<div class="dialog-actions"><button id="onlineSubmitBack" class="secondary">'+(returnToResult?'回到結算':'完成')+'</button></div>','online-submit');if(returnToResult)$('utilityDialog').dataset.returnToResult='yes';$('onlineSubmitBack').onclick=()=>{if(returnToResult)showResult();else $('utilityDialog').close();};
 if(!eligible.ok)return;const form=$('onlineSubmitForm');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]'),input=$('onlineNickname');button.disabled=input.disabled=true;$('onlineSubmitStatus').textContent='正在提交成績…';try{const receipt=await online.submit(r,input.value.trim(),Number(form.querySelector('input[name=avatarId]:checked').value));if(!form.isConnected)return;form.innerHTML='<div class="feedback-received"><strong>成績已提交！</strong><p>'+(receipt.rank?'你目前在'+(r.mode==='life'?'人生模式':'自由模式')+(r.status==='won'?'超額報酬榜':'翻車紀錄榜')+'的最佳名次：<b>第 '+receipt.rank.rank+' 名</b>。':'成績已加入線上紀錄。')+'</p></div>';}catch(err){if(!form.isConnected)return;button.disabled=input.disabled=false;$('onlineSubmitStatus').textContent=err.message;$('onlineSubmitStatus').className='online-status error';}};
}

function showRunStats(kind){
 syncPlaytime();
 const isBest=kind==='best',r=isBest?TaiguRecords.best(book,state.mode):(hasProgress()?TaiguRecords.snapshot(market,state):book.runs.at(-1));
 if(!r){utility(isBest?'最佳遊玩數據':'上次遊玩數據',`<div class="record-empty"><span>${isBest?'♧':'🌱'}</span><h3>${isBest?'第一個結局，還在等你。':'你的第一輪冒險，還沒開始。'}</h3><p>${isBest?'完整一輪結算後，這裡會依超額報酬留下最佳成績；進行中或重開的紀錄不列入。':'開始遊戲後，這裡會顯示最近一輪的真實遊玩數據。'}</p></div>`);return;}
   utility(isBest?'最佳遊玩數據':'上次遊玩數據',runStatsHTML(r),'records');
}
function runStatsHTML(r,shared=false){
const labels={playing:r.reason==='restarted'?'中途重新開始':'冒險進行中',won:'成功超越 0050',lost:'未能超越 0050',bankrupt:'資產耗盡', 'awaiting-data':'等待資料補齊'};
 return `<section class="run-verdict" data-status="${esc(r.status)}"><span>${r.mode==='life'?'人生模式':'自由／舊版'}</span><strong>${esc(labels[r.status])}</strong></section><h3>${esc(r.date)} · 第 ${r.sessions} 個交易日</h3><div class="result-card"><div><span>小韭總資產</span><b>${dollars(r.equity)}</b></div><div><span>0050 平行人生</span><b>${dollars(r.benchmark)}</b></div></div><p class="result-number">${(r.alpha>=0?'+':'')+r.alpha.toFixed(2)} <small>百分點</small></p><div class="record-details"><div><span>總報酬</span><b>${pct(r.returnPct)}</b></div><div><span>最大回撤</span><b>${r.maxDrawdown.toFixed(2)}%</b></div><div><span>交易次數（成交）</span><b>${r.trades} 筆</b></div><div><span>劇情選擇</span><b>${r.choices} 次</b></div><div><span>累積手續費</span><b>${dollars(r.fees)}</b></div><div><span>累積交易稅</span><b>${dollars(r.tax)}</b></div><div><span>劇情支出</span><b>${dollars(r.spent)}</b></div><div><span>剩餘現金</span><b>${dollars(r.cash)}</b></div></div>${playStats(r)}${highlightsHTML(r)}${shared?'':'<p class="muted-note">最佳紀錄依已結算輪次的超額報酬排序，打平時比較總資產。提交成績時會附上遊玩時長與技能次數，供管理後台查看。</p>'}`;
}
function enterGame(){market.enableSkills(state,{});if(progression.marginUnlocked)market.enableMargin(state);if(state.day===-1)online.start(state).catch(()=>{});screen='game';syncPlaytime();$('titleScreen').hidden=true;$('gameShell').hidden=false;document.body.classList.remove('at-title');resultShown=false;render(true);if(state.opening)showIntro();else if(TaiguTutorial.needs(state,tutorialProfile))showTutorial(true);else if(theatre.pending(state))resumeSupport();}
function showTitle(){if(busy)return;syncPlaytime(false);save();screen='title';syncPlaytime(false);previewMode=null;for(const d of document.querySelectorAll('dialog[open]'))d.close();$('gameShell').hidden=true;$('titleScreen').hidden=false;document.body.classList.add('at-title');renderTitle();syncMusic();communityHome.refresh();for(const r of book.runs)communityHome.report(r);window.scrollTo(0,0);setTimeout(()=>{if(incomingShare){openIncomingShare();checkAnnouncement();return;}showUnlockNotice();checkAnnouncement();tryAnnouncement();},90);}
function restartGame(mode=requestedMode){if(typeof mode!=='string')mode=requestedMode;if(mode==='free'&&!progression.freeUnlocked){notify('完成人生模式才可進行自由模式。');return;}
 if(hasProgress())rememberRun(state.status==='playing'?'restarted':'completed');
 state=identify(market.fresh(mode,progression.marginUnlocked,skillProfile.levels));creditMode='cash';lastReply='';recordSignature='';resultShown=false;selected='0050';side='buy';quantityMode='fixed';chart.offset=0;$('utilityDialog').close();save();enterGame();
}
function startFromMenu(mode='life'){requestedMode=mode;if(mode==='free'&&!progression.freeUnlocked)return;
 if(!hasProgress()){restartGame();return;}
 utility('重新開始一輪冒險？','<p>目前進度會整理成上次遊玩數據，再從一百萬元重新開始。要保留目前旅程，請先到存檔管理儲存進度。</p><div class="dialog-actions"><button class="primary" id="startFresh">開始新的轉生</button><button class="secondary" id="keepPlaying">繼續原本的旅程</button></div>');
 $('startFresh').onclick=restartGame;$('keepPlaying').onclick=()=>{$('utilityDialog').close();enterGame();};
}
function resumeState(loaded){syncPlaytime(false);quantityMode='fixed';state=loaded;lastReply='';resultShown=false;storageFailed=false;$('utilityDialog').close();syncEvent();save();enterGame();}
function showAbout(){
 utility('關於台股戰士','<div class="about-lead"><span class="about-mark" aria-hidden="true">韭</span><div><h3>台股戰士</h3><p>小韭的第二次開盤 · 原型 '+TaiguCommunity.VERSION+'</p></div></div><p>一個聽過太多明牌的打工人，帶著一百萬元回到 2020 年。這次能不能靠自己的決定，贏過那個只買 0050 的平行人生？</p><dl class="about-facts"><dt>人生模式</dt><dd>跟著事件前進，每次開放三個交易日決定買賣。</dd><dt>自由模式</dt><dd>完成人生模式一輪後解鎖，每個交易日都能操作。</dd><dt>歷史舞台</dt><dd>'+esc(data.start.replaceAll('-','/'))+'—'+esc(data.end.replaceAll('-','/'))+'，搭配真實行情、新聞事件與虛構劇情。</dd><dt>創作方式</dt><dd>本專案使用 AI 輔助開發，包含程式、劇情與美術素材。</dd></dl><div class="about-bottom">進度可在存檔管理中儲存，之後讀取繼續。<br><a href="https://github.com/00160530/StockFighterAJO" target="_blank" rel="noopener noreferrer">GitHub 專案 ↗</a></div>','about');
}
function showUpdates(){
 const items=(window.TAIGU_UPDATES||[]).slice().sort((a,b)=>b.date.localeCompare(a.date)||b.version.localeCompare(a.version,undefined,{numeric:true}));
 if(announcement)markAnnouncement(announcement.publishedAt);utility('更新及公告','<div class="announcement-list">'+(announcement?announcementHTML(announcement):'')+items.map((a,i)=>'<article class="announcement-item"><header><b>v'+esc(a.version)+'</b><time>'+esc(a.date.replaceAll('-','/'))+'</time>'+(i===0?'<span>最新更新</span>':'')+'</header><h3>'+esc(a.title)+'</h3><ul>'+a.details.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul></article>').join('')+'</div>','updates');
}
function showFeedback(){
 utility('許願池及問題回報','<p class="feedback-note">想多看到什麼，或遇到哪裡卡住？把想法寫下來，送出後作者可在管理後台查看。</p><form id="feedbackForm" class="feedback-form"><fieldset class="feedback-types"><legend>內容類型</legend><label><input type="radio" name="feedbackKind" value="wish" checked>✧ 許願池</label><label><input type="radio" name="feedbackKind" value="problem">⚑ 問題回報</label></fieldset><label class="feedback-field"><span id="feedbackTitleLabel">一句話說說你的願望</span><input id="feedbackTitle" required minlength="2" maxlength="80" placeholder="例如：想讓群組裡出現更多散戶神回覆"></label><label class="feedback-field"><span id="feedbackBodyLabel">想多看到什麼？</span><textarea id="feedbackBody" required minlength="5" maxlength="2000" placeholder="可以寫想要的功能、劇情，或遇到的問題。"></textarea><small id="feedbackCount">0 / 2000</small></label><label id="feedbackStepsField" class="feedback-field steps" hidden><span>怎麼遇到的？（選填）</span><textarea id="feedbackSteps" maxlength="1000" placeholder="例如：讀取進度 → 按下一事件 → 畫面停住"></textarea></label><label class="feedback-context"><input id="feedbackContext" type="checkbox" checked>附上目前遊戲日期與模式，方便確認問題</label><p class="online-submit-note">送出內容與遊戲版本會存至雲端；不含完整存檔。表單不保留草稿。</p><p id="feedbackStatus" class="online-status" role="status"></p><div class="feedback-actions"><button type="submit" class="primary">送出</button></div></form>','feedback');
 const form=$('feedbackForm'),requestId=crypto.randomUUID();
 function updateLabels(){const problem=form.elements.feedbackKind.value==='problem';$('feedbackStepsField').hidden=!problem;$('feedbackTitleLabel').textContent=problem?'一句話說明問題':'一句話說說你的願望';$('feedbackBodyLabel').textContent=problem?'遇到了什麼狀況？':'想多看到什麼？';$('feedbackTitle').placeholder=problem?'例如：播放到下一事件時畫面停住':'例如：想讓群組裡出現更多散戶神回覆';}
 form.addEventListener('input',()=>{updateLabels();$('feedbackCount').textContent=$('feedbackBody').value.length+' / 2000';});
 form.onsubmit=async e=>{e.preventDefault();const body={requestId,kind:form.elements.feedbackKind.value,title:$('feedbackTitle').value.trim(),body:$('feedbackBody').value.trim(),steps:$('feedbackSteps').value.trim(),version:TaiguCommunity.VERSION,context:$('feedbackContext').checked?{date:state.day<0?'2020-01-01':market.date(state),mode:state.mode}:null,website:''};const button=form.querySelector('button[type=submit]');button.disabled=true;$('feedbackStatus').textContent='送出中…';try{const r=await online.feedback(body);if(!form.isConnected)return;form.innerHTML='<div class="feedback-received"><strong>已收到，謝謝你！</strong><p>作者可以在管理後台看到這則'+(body.kind==='wish'?'願望':'問題回報')+'。</p><small>回報編號 '+esc(r.id)+'</small><button id="feedbackDone" class="primary" type="button">完成</button></div>';$('feedbackDone').onclick=()=>$('utilityDialog').close();}catch(err){if(!form.isConnected)return;button.disabled=false;$('feedbackStatus').textContent=err.message;$('feedbackStatus').className='online-status error';}};
}

function savedProgress(p){const a=p?.state;if(!a)return null;const date=a.day<0?'2020-01-01':a.history?.at(-1)?.date||data.calendar[a.day]||'日期不明';const time=new Date(p.savedAt);return {duration:TaiguPlaytime.format(a.playTimeMs),partial:a.playTimePartial||!Number.isFinite(a.playTimeMs),date,mode:a.mode==='free'?'自由模式':'人生模式',status:a.status==='playing'?'冒險中':a.status==='awaiting-data'?'等待追加日期':'已結算',time:Number.isFinite(time.getTime())?new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(time):'未記錄'};}
function showSaves(afterResult=false){syncPlaytime();afterResult=afterResult===true;const canStore=screen==='game',canLoad=screen==='title';
 const current=state.day<0?'2020-01-01':market.date(state);
 let html='<div class="save-intro"><p>可中途儲存，之後讀取繼續。到達資料終點後也能保存，待追加交易日期後接著玩。</p><div class="save-current"><span>目前遊戲進度 <b>'+esc(current.replaceAll('-','/'))+'</b><small>遊玩時長 '+TaiguPlaytime.format(state.playTimeMs)+(state.playTimePartial?'（從新版開始累計）':'')+'</small></span><button class="secondary" id="exportLog">操作紀錄 CSV ↗</button></div></div><div class="save-slots">';
 for(let i=1;i<=3;i++){let pack;try{pack=JSON.parse(localStorage.getItem(KEY+'.slot'+i)||'null');}catch{}const d=savedProgress(pack);html+='<article class="save-slot"><div class="save-copy"><strong>進度 '+i+' <em>'+(d?esc(d.mode)+' · '+esc(d.status):'空欄位')+'</em></strong>'+(d?'<span>遊戲進度：<b>'+esc(d.date.replaceAll('-','/'))+'</b></span><small>遊玩時長：'+(Number.isFinite(pack.state.playTimeMs)?esc(d.duration)+(d.partial?'（從新版開始累計）':''):'尚無紀錄')+'</small><small>實際儲存：'+esc(d.time)+'（台北時間）</small>':'<span>尚未儲存，可將目前旅程留在這裡。</span>')+'</div><div class="save-actions"><button class="secondary" data-store="'+i+'" '+(canStore?'':'disabled')+'>儲存</button><button class="secondary" data-load="'+i+'" '+(d&&canLoad?'':'disabled')+'>'+(canLoad&&pack?.state?.status==='playing'?'讀取繼續':'讀取')+'</button></div></article>';}
 html+='</div><div class="save-footer"><button class="primary" id="saveDone">完成，回到起始畫面</button></div>';
 utility(afterResult?'保存本輪進度':'存檔管理',html,'saves');$('exportLog').onclick=()=>{
  const cell=x=>{let s=String(x??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const fields=['date','type','text','id','side','qty','price','value','fee','tax','costBasis','realizedPnl','sizeMode','financing','borrowed','repaid','interestPaid','forced'];download('台股戰士-操作紀錄.csv','\ufeff'+[fields,...state.log.map(l=>fields.map(f=>l[f]))].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');
 };
 document.querySelectorAll('[data-store]').forEach(b=>b.onclick=()=>{if(!canStore)return;if(writeStorage(KEY+'.slot'+b.dataset.store,pack())){notify('已儲存到進度 '+b.dataset.store);showSaves(afterResult);}});
 document.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{if(!canLoad)return;try{const p=JSON.parse(localStorage.getItem(KEY+'.slot'+b.dataset.load));resumeState(validateState(p.state));notify('已讀取存檔。');}catch(e){notify('讀取失敗：'+e.message);}});
 $('saveDone').onclick=showTitle;
}
function showHelp(){
 const categories=[
 ['遊戲目標','<h3>打敗只買 0050 的自己</h3><p>帶著本金 100 萬元從 2020 年 1 月重新開始。到 2026 年 10 月 16 日，總資產必須嚴格高於 0050 股利再投入的平行人生；相同或落後即未達成。持股與應收股利都算資產，融資和技能借款會扣除。淨資產耗盡會提前結束。</p><p>完成完整一輪人生模式，無論勝負，都會解鎖自由模式及融資。提前破產不算完成。</p>'],
 ['遊戲方式','<h3>人生模式與自由模式</h3><p>人生模式透過事件推進，事件當日與後兩個交易日可委託，並有趣味事件。可提早結束操作，前往下一事件。自由模式每天都可交易，保留原有劇情及新聞。</p><h3>委託與成交</h3><ol><li>選擇 ETF 或個股，輸入股數與買賣方向。</li><li>送出委託，於下一交易日開盤撮合；成交前可在待成交頁取消。</li><li>推進日期，查看收盤行情與庫存。</li></ol><p>全部買進按次日開盤價買入可負擔的最大整數股數；全部賣出出售當時全部可賣持股。多筆委託依提交順序使用剩餘現金，資金不足則整筆取消。融資與現股的庫存分開委託。</p><h3>看盤與播放</h3><p>K 棒採紅漲綠跌，顯示均線、成交量與延後一交易日的法人資料。拖曳回看、滾輪縮放；回到今日恢復最新位置。播放速度「跳轉」加速安靜日期，遇到劇情、追繳或操作期仍會停下，交易、利息、股利與分割逐日結算。</p><h3>費用與模擬範圍</h3><p>手續費 0.1425%，每筆至少 20 元；賣出 ETF 稅 0.1%，個股 0.3%。整數股交易，零股同樣按開盤價，未模擬 T+2、撮合佇列與流動性。初始本金不會自動增加薪資或扣生活費，劇情支出會列入績效。</p>'],
 ['趣味事件','<h3>手指支撐線</h3><p>人生模式在前一交易日已公布的法人合計賣超至少 100 億、當日大盤跌至少 2%，且原本持股下跌收黑時，會出現賣壓小劇場。畫面逐漸變暗、K 棒往下後，詢問是否使用手指支撐線。選擇使用後連續點擊撐住股價。</p><p>所有持股共用 30 個交易日冷卻，選擇不出招也計入冷卻。演出結果與選擇會留下紀錄。</p><h3>事件與新聞</h3><p>K 線標記可點開閱讀；事件多時會錯開或收合，以免遮住行情。新聞與群組只顯示目前遊戲日期以前的內容。</p>'],
 ['融資說明',TaiguMarginUI.help()],
 ['技能與二周目','<h3>技能點怎麼獲得</h3><p>完整完成人生模式，未打敗大盤得 1 點，打敗得 2 點；總資產嚴格超過 0050 平行人生的 1.5 倍得 3 點，超過 2 倍得 4 點。每輪只領一次，提前破產不算完成。</p><p>只能在起始畫面升級，每級花 1 點，下一輪套用；遊戲中只能使用已學技能。</p><h3>媽媽10塊</h3><p>5 級，每級 20 萬借款額度。借款半年後還款，遊戲結束時也會結清；已使用額度不恢復。</p><h3>林北VIP拉</h3><p>5 級，每級 20 萬額度。追繳期間可請券商代墊，補到約 166.67%；不足以補足時不能使用。融資部位結清或遊戲結束時還款，已使用額度不恢復，代墊會列為負債。</p><h3>奇門遁甲</h3><p>3 級，每級 1 次。預測未來 10 個交易日上漲、下跌、平盤的日數，不顯示幅度。</p>'],
 ['存檔紀錄','<h3>保存與繼續旅程</h3><p>遊戲中可儲存到 3 個進度欄位；回起始畫面後可讀取繼續。遊戲結束先顯示結算，確認後可保存。若未來追加交易日期，也能讀取已完成的進度接著玩。</p><p>存檔分別顯示遊戲進度日期、實際儲存時間（台北時間）及遊玩時長。首頁只能讀取，遊戲中只能儲存。</p><h3>遊玩時長與個人數據</h3><p>在遊戲中且視窗位於前景時累計；切到背景、離開視窗或回起始畫面即暫停。讀檔後接續累計，舊存檔從新版開始記錄。個人遊玩數據顯示時長、技能成功使用次數、成交與融資統計。</p><p>提交排行榜會一併上傳時長與技能次數，供管理後台查看；公開排行榜不顯示這兩項。</p>']
 ];utility('遊戲說明','<div class="help-layout"><nav class="help-categories" aria-label="說明分類">'+categories.map(([name],i)=>'<button class="secondary" data-help="'+i+'" aria-pressed="'+(i===0)+'">'+name+'</button>').join('')+'</nav><section id="helpArticle" class="help-article" aria-live="polite">'+categories[0][1]+'</section></div>','help');
 document.querySelectorAll('[data-help]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-help]').forEach(b=>b.setAttribute('aria-pressed',b===button));$('helpArticle').innerHTML=categories[Number(button.dataset.help)][1];$('utilityContent').scrollTop=0;});
}
async function copyShareText(input,status){try{await navigator.clipboard.writeText(input.value);status.textContent='已複製，可以貼到 LINE 傳給朋友！';}catch{input.focus();input.select();status.textContent='請長按或按 Ctrl+C 複製文字。';}}
function showPromote(){utility('協助推廣','<h3>揪朋友一起重來一次！</h3><p>複製下面這段文字，貼到 LINE 就能推薦給朋友。</p><textarea id="promotionText" class="share-text" readonly aria-label="推薦文字">'+esc(TaiguShare.promotion)+'</textarea><div class="dialog-actions"><button id="copyPromotion" class="primary">複製推薦文字</button></div><p id="promotionStatus" role="status"></p>','promote');$('copyPromotion').onclick=()=>copyShareText($('promotionText'),$('promotionStatus'));}
async function shareBestRecord(){const r=TaiguRecords.best(book,state.mode);if(!r)return;const requestId=identify({...r,runId:r.id}).runId,record=TaiguShare.payload(r);utility('炫耀一下','<div class="share-processing" role="status"><i aria-hidden="true"></i><h3>正在處理中…</h3><p>正在製作你的股神紀錄連結。</p></div>','share-processing');try{const result=await online.share(record,requestId);if(!$('utilityDialog').open||$('utilityDialog').dataset.view!=='share-processing')return;const link=TaiguShare.link(result.id);utility('股神紀錄準備好了！','<p>把連結貼到 LINE，朋友打開就會看到這份最佳紀錄。</p><input id="sharedLink" class="share-link" readonly aria-label="紀錄分享連結" value="'+esc(link)+'"><div class="dialog-actions"><button id="copySharedLink" class="primary">複製連結</button></div><p id="sharedLinkStatus" role="status"></p>','share-ready');$('copySharedLink').onclick=()=>copyShareText($('sharedLink'),$('sharedLinkStatus'));}catch(e){if(!$('utilityDialog').open||$('utilityDialog').dataset.view!=='share-processing')return;utility('暫時無法產生連結','<p>'+esc(e.message)+'</p><div class="dialog-actions"><button id="retryShare" class="primary">再試一次</button></div>','share-error');$('retryShare').onclick=shareBestRecord;}}
async function openIncomingShare(){if(shareLoading||!incomingShare)return;shareLoading=true;const id=incomingShare;incomingShare=null;utility('你朋友股神的紀錄','<div class="share-processing" role="status"><i aria-hidden="true"></i><p>正在讀取朋友的紀錄…</p></div>','shared-record');try{if(!/^[a-zA-Z0-9_-]{8,120}$/.test(id))throw Error('分享連結格式不正確。');const result=await online.sharedRecord(id);if($('utilityDialog').open&&$('utilityDialog').dataset.view==='shared-record')utility('你朋友股神的紀錄',runStatsHTML(result.record,true),'shared-record');}catch(e){if($('utilityDialog').open&&$('utilityDialog').dataset.view==='shared-record')utility('你朋友股神的紀錄','<p>'+esc(e.message)+'</p>','shared-record');}finally{shareLoading=false;}}
function showResetRecords(){utility('刪除全部紀錄','<h3>將這個瀏覽器恢復成第一次開啟</h3><p>會清除本機遊戲進度、3 個存檔、遊玩數據、技能點、解鎖狀態、暱稱偏好及音樂設定。清除後無法復原。</p><p>已上傳的排行榜成績、回報及作者公告仍保留在雲端；清除後會建立新的匿名玩家身分。</p><div class="dialog-actions"><button id="cancelReset" class="secondary">保留紀錄</button><button id="confirmReset" class="secondary danger">確定刪除全部本機紀錄</button></div><p id="resetError" role="status"></p>','reset');$('cancelReset').onclick=()=>$('utilityDialog').close();$('confirmReset').onclick=()=>{try{resettingRecords=true;syncPlaytime(false);playback.stop();TaiguLocalRecords.clear(localStorage);location.reload();}catch(e){resettingRecords=false;$('resetError').textContent='清除未完成：'+e.message;}};}

function showData(){utility('資料來源與計算規則',`<h3>已收錄的真實資料</h3><p>${data.start} 至 ${data.end}，共 ${data.calendar.length.toLocaleString()} 個交易日。另含 2019 年 10 月起的暖機資料，供開局均線計算使用。</p><p>大盤與四檔標的的每日開高低收、成交股數、成交金額，三大法人、現金股利，來自 <a href="https://finmind.github.io/" target="_blank" rel="noopener">FinMind</a>。完整查詢網址、資料筆數與下載時間列在 <a href="data/provenance.json" target="_blank" rel="noopener">provenance.json</a>。</p><h3>公平的時間線</h3><p>開局為 2020 元旦休市，只能看到 2019/12/31 以前的行情；第一筆委託於 2020/01/02 開盤撮合。後續只顯示遊戲日期以前的價格，法人只顯示上一交易日以前的資料。股利與分割於歷史生效日處理，不會提前反映在資產。</p><h3>0050 基準</h3><p>同樣一百萬元，第一日開盤以可負擔的最大整數股數買進 0050，支付相同手續費。除息日建立應收股利，實際發放後於第一個有報價的開盤再投入。剩餘現金與應收股利計入資產。兩者都按收盤市值比較，未持有部位才產生賣出稅費；不假設期末強制清倉。</p><h3>分割與暫停交易</h3><p>0050 在 2025/06/11—06/17 暫停交易，該期間無 K 棒，不虛構成交；持股沿用最近收盤估值。2025/06/18 持股數乘四、總成本不變。圖表預設勾選分割還原，只套用當時已發生的分割。參見<a href="https://www.twse.com.tw/zh/ETFortune/announcement?company=A00005&date=20250617&fund=0050&seq=1&type=other" target="_blank" rel="noopener">證交所分割公告</a>。</p><h3>單位與缺值</h3><p>成交量是股；個股法人是買賣超股數，大盤法人是買賣超金額（元）。缺少法人資料的日期留白；不會以零或模擬數據代替。</p><h3>資料與本機儲存</h3><p>遊玩時不連接行情服務。所有歷史資料均隨網頁提供，進度存在瀏覽器 localStorage。線上排行榜與主動送出的回報透過 Worker 寫入 D1，完整存檔仍只在本機。更新資料需在本機執行下載工具，再重新上傳靜態檔案。</p><p class="muted-note">資料供應商可能更正歷史紀錄。公開再散布前需確認供應商與原始來源的授權範圍；原始素材圖的生成提示詞與檔案資訊收錄於 docs/ASSETS.md。</p>`);}
function endingHighlights(r){const card=(t,label,empty)=>'<article><small>'+label+'</small><strong'+(t?' class="'+tone(t.pnl)+'"':'')+'>'+(t?(t.pnl>=0?'+':'−')+dollars(Math.abs(t.pnl)):empty)+'</strong><span>'+(t?esc(t.id)+' · '+esc(t.date)+' · '+fmt(t.qty)+' 股':'完成賣出後留下紀錄')+'</span></article>';return '<div class="ending-highlights">'+card(r.maxGain,'最大獲利・單筆淨收益','尚無獲利賣出')+card(r.maxLoss,'最大虧損・單筆淨收益','尚無虧損賣出')+'</div>';}
function showResult(){
 syncPlaytime(false);
 syncProgression();const d=market.date(state),e=market.equity(state,d),b=market.equity(state.benchmark,d),alpha=(e-b)/1e6*100,r=TaiguRecords.snapshot(market,state),h=r.highlights;
 const title=state.bankruptcyReason==='margin-debt'?'融資斷頭，這次連本金都不夠還。':state.status==='won'?'這次，你超越了平行人生。':state.status==='bankrupt'?'本金耗盡，這輪先下市。':state.status==='awaiting-data'?'資料暫時到這裡。':'你活到了最後，卻沒能贏過 0050。';
 utility('本輪結算', '<div class="ending-heading"><span>'+(state.mode==='life'?'人生模式':'自由模式')+' · '+esc(d.replaceAll('-','/'))+'</span><h3>'+title+'</h3></div><div class="result-card"><div><span>小韭總資產</span><b>'+dollars(e)+'</b></div><div><span>0050 平行人生</span><b>'+dollars(b)+'</b></div></div><p class="result-number">'+(alpha>=0?'+':'')+alpha.toFixed(2)+' <small>超額報酬・百分點</small></p><div class="ending-trades"><span>成交交易 <b>'+r.trades+' 筆</b></span><span>累積手續費 <b>'+dollars(r.fees)+'</b></span><span>交易稅 <b>'+dollars(r.tax)+'</b></span></div>'+marginRecords(r)+(state.bankruptcyReason==='margin-debt'&&state.cash<0?'<p class="unlock-notice">🏅 成就：負債轉生</p>':'')+playStats(r)+endingHighlights(r)+(state.mode==='life'&&['won','lost'].includes(state.status)&&progression.freeUnlocked?'<p class="unlock-notice">✦ 自由模式已解鎖</p>':'')+'<div class="ending-actions"><button class="secondary" id="resultSubmit">提交線上排行</button><button class="primary" id="resultConfirm">確定，保存進度 →</button></div>','result');
 $('resultConfirm').onclick=()=>showSaves(true);$('resultSubmit').onclick=()=>showOnlineSubmit(r);if(online.receipt(r.id))$('resultSubmit').textContent='查看已提交成績';setTimeout(showUnlockNotice,100);
}
