// Bind interface events once; all mutations go through the game engine.
 $('nextBtn').onclick=()=>advance(1);$('lifeSkipBtn').onclick=()=>advance(1,true);$('weekBtn').onclick=()=>advance(5);$('monthBtn').onclick=()=>advance(20);
