 $('eventsToggle').onchange=()=>{chart.showEvents=$('eventsToggle').checked;chart.draw();};$('maToggle').onchange=()=>{chart.ma=$('maToggle').checked;chart.draw();};$('adjustToggle').onchange=()=>{chart.adjust=$('adjustToggle').checked;render();};$('chartReset').onclick=()=>{chart.offset=0;chart.hover=null;chart.draw();};
 $('inventoryBtn').onclick=showInventory;$('pausePlayback').onclick=()=>playback.stop();$('playbackSpeed').onchange=()=>{try{localStorage.setItem(KEY+'.playbackSpeed',$('playbackSpeed').value);}catch{}};
 $('storyGroupBtn').onclick=showGroup;$('newsBtn').onclick=()=>showNews();$('highlightsBtn').onclick=showCurrentHighlights;$('menuRankings').onclick=()=>showLeaderboard();
 $('saveBtn').onclick=showSaves;$('helpBtn').onclick=showHelp;$('dataBtn').onclick=showData;$('closeUtility').onclick=()=>{if($('utilityDialog').dataset.view==='result')showSaves(true);else if($('utilityDialog').dataset.view==='online-submit'&&$('utilityDialog').dataset.returnToResult==='yes')showResult();else $('utilityDialog').close();};$('utilityDialog').addEventListener('cancel',e=>{if($('utilityDialog').dataset.view==='result'){e.preventDefault();showSaves(true);}else if($('utilityDialog').dataset.view==='online-submit'&&$('utilityDialog').dataset.returnToResult==='yes'){e.preventDefault();showResult();}});
 document.querySelector('#gameMenu nav').addEventListener('click',e=>{if(e.target.closest('button'))$('gameMenu').open=false;});
 document.addEventListener('click',e=>{if(!tutorial.active&&!e.target.closest('#gameMenu'))$('gameMenu').open=false;});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!tutorial.active)$('gameMenu').open=false;});
 function sayTitleQuip(){const q=nextTitleQuip(),el=$('titleCharacter'),bubble=$('titleBubble'),mobile=$('titleMobileQuip'),face=typeof q.emotion==='number'?q.emotion:0;bubble.textContent=mobile.textContent=q.text;mobile.dataset.speaking='true';clearTimeout(titleQuipTimer);titleQuipTimer=setTimeout(()=>{delete mobile.dataset.speaking;},4500);el.dataset.face=q.emotion==='serious'?'serious':'';el.style.setProperty('--sprite-x',(face%3)*50+'%');el.style.setProperty('--sprite-y',Math.floor(face/3)*100+'%');}
 let titlePointerType='mouse';$('titleCharacter').addEventListener('pointerdown',e=>{titlePointerType=e.pointerType;});$('titleCharacter').addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')sayTitleQuip();});$('titleCharacter').addEventListener('pointerleave',()=>{const el=$('titleCharacter');delete el.dataset.face;el.style.setProperty('--sprite-x','0%');el.style.setProperty('--sprite-y','0%');});$('titleCharacter').onclick=e=>{if(e.detail===0||titlePointerType==='touch')sayTitleQuip();};$('titleCharacter').onfocus=()=>{if($('titleCharacter').matches(':focus-visible'))sayTitleQuip();};
 $('supportMute').onclick=()=>music.setEnabled(!music.enabled);$('bgmSettings').onclick=showMusic;$('menuStart').onclick=()=>startFromMenu('life');$('menuFree').onclick=()=>startFromMenu('free');$('menuContinue').onclick=enterGame;$('menuSaves').onclick=showSaves;$('menuLast').onclick=()=>showRunStats('last');$('menuBest').onclick=()=>showRunStats('best');$('menuHelp').onclick=showHelp;$('menuReset').onclick=showResetRecords;$('menuPromote').onclick=showPromote;$('homePollTitle').onclick=$('pollHistoryBtn').onclick=()=>communityHome.history();$('shareBest').onclick=shareBestRecord;$('homeBtn').onclick=showTitle;
